class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if not s or k > len(s):
            return 0

        count = {}
        for c in s:
            count[c] = count.get(c, 0) + 1

        split_char = None
        for c, cnt in count.items():
            if cnt < k:
                split_char = c
                break

        if split_char is None:
            return len(s)

        max_len = 0
        for sub in s.split(split_char):
            max_len = max(max_len, self.longestSubstring(sub, k))

        return max_len
